{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is neither documented nor explicitly ruled out."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "Construction and scoring are described narrowly enough to interpret the reported puzzle performance. Repeatability, comparison conditions, and broader applicability remain undocumented."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "A single evaluation supplies no evidence of stability or instability across runs."
        }
      ],
      "instrument_review": "The score describes one evaluation of the specified puzzles. The documented absence of repetition limits consistency claims; it does not demonstrate unstable performance."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The passage documents repeated evaluations under the same stated conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability definition of at most two percentage points."
        }
      ],
      "instrument_review": "Repeated testing supports consistency under the stated conditions and explicit stability criterion. This evidence remains limited to the tested system, puzzles, and settings; it does not establish broader generalization or comparative fairness."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under the same stated conditions is explicitly documented."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The reported variation exceeds the defined stability limit of two percentage points."
        }
      ],
      "instrument_review": "The repeated results document a consistency problem under the report's criterion. Reporting 70% alone would inadequately convey this variation; comparisons should account for the repeated results."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not document repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence about score consistency."
        }
      ],
      "instrument_review": "Installation documentation explains setup, but does not strengthen the evaluation evidence. Repeatability and stability remain unestablished, and the score's interpretation remains limited to the reported puzzle run."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher score on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The results provide no evidence establishing superiority across domains."
        }
      ],
      "instrument_review": "The observed comparison matches the intended narrow use. Fixed instructions and exact-grid scoring support interpretation, but repeated-run consistency and other conditions needed to assess fair comparisons are unspecified."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply evidence of general intelligence across domains."
        }
      ],
      "instrument_review": "The intended selection use exceeds the supplied evidence. The results support a puzzle-specific comparison, while cross-domain interpretation, repeated-run consistency, and complete comparison conditions remain unsupported or undocumented."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Those scores alone do not establish an improvement in real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized, preregistered trial supports higher correctness with A; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved correctness does not establish an effect on an unmeasured safety outcome."
        }
      ],
      "instrument_review": "Random allocation, preregistration, blinded correctness assessment, and reported uncertainty strengthen evidence for the intended workshop-specific choice. The trial supports correctness under the studied conditions; effects on time, safety, or other workshops remain unestablished."
    }
  ],
  "closing_note": "No instructions were unclear. Missing evidence was distinguished from explicit contradiction, and each case was assessed independently."
}
